"""Auto-generated task catalog (issue #42).

`bench catalog` renders the task corpus to `docs/TASKS.md`: one section per
category, each a table of id, title, difficulty, and tags. Only `task.yaml`
fields are read — the hidden rubric (`expected.json`) and reference answer
(`solution.json`) are never consulted, so no root-cause detail can leak into
the catalog. CI regenerates the file and fails on any diff, keeping it in sync
with the corpus.
"""

from __future__ import annotations

from pathlib import Path

from bench.tasks import TaskResult, difficulty_distribution, load_tasks

CATALOG_HEADER = """\
# Task Catalog

<!-- Auto-generated by `python -m bench catalog`; do not edit by hand.
     CI regenerates this file and fails if it is stale. -->"""


def _cell(text: str) -> str:
    """Escape text for a Markdown table cell."""
    return text.replace("|", "\\|")


def _task_row(result: TaskResult) -> str:
    config: dict = result.config or {}
    difficulty = str(config.get("difficulty") or "-")
    title = str(config.get("title") or "-")
    tags = ", ".join(str(tag) for tag in (config.get("tags") or [])) or "-"
    return (
        f"| {result.id} | {_cell(title)} | {difficulty} | {_cell(tags)} |"
    )


def _plural(count: int, word: str) -> str:
    if count == 1:
        return f"1 {word}"
    # "category" -> "categories"; otherwise a plain "s".
    stem = word[:-1] + "ies" if word.endswith("y") else word + "s"
    return f"{count} {stem}"


def render_catalog(results: list[TaskResult]) -> str:
    """Render the catalog Markdown for a list of task results.

    Pure: grouped by category (alphabetical), tasks sorted by id within each
    category. Tasks whose `task.yaml` failed to parse still appear with `-`
    placeholders so a broken task is visible in the catalog, not hidden.
    """
    by_category: dict[str, list[TaskResult]] = {}
    for result in sorted(results, key=lambda item: (result_category(item), item.id)):
        by_category.setdefault(result_category(result), []).append(result)

    distribution = difficulty_distribution(results)
    distribution_text = ", ".join(
        f"{count} {level}" for level, count in distribution.items()
    )
    lines = [
        CATALOG_HEADER,
        "",
        f"{_plural(len(results), 'task')} in {_plural(len(by_category), 'category')}: "
        f"{distribution_text} (difficulty rubric: AGENTS.md).",
    ]

    for category in sorted(by_category):
        lines.append("")
        lines.append(f"## {category}")
        lines.append("")
        lines.append("| ID | Title | Difficulty | Tags |")
        lines.append("| --- | --- | --- | --- |")
        lines.extend(_task_row(result) for result in by_category[category])

    return "\n".join(lines).rstrip("\n") + "\n"


def result_category(result: TaskResult) -> str:
    """Category label for grouping; falls back to the parent folder name."""
    config = result.config or {}
    category = config.get("category")
    if isinstance(category, str) and category.strip():
        return category
    return result.path.parent.name


def cmd_catalog(root: Path, output: Path) -> int:
    """Render the catalog for `root` and write it to `output`."""
    text = render_catalog(load_tasks(root))
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(text, encoding="utf-8")
    print(f"wrote {output}")
    return 0
